est,Capability=safetyCapability,Operator=FleetCapabilityOperators.Equals,RequiredBooleanValue=true,IsMandatory=true});request.Priority=FleetPriorities.Emergency;request.EmergencyReason="QA emergency";request.ReportedByUserId=users["requester"].Id;request.ReportedAt=fixedAt.AddHours(6);request.IncidentLocation="QA origin";request.EmergencyPolicy=policy;request.EmergencyPolicyCode=policy.Code;request.ResponseTargetMinutesSnapshot=15;request.DispatchTargetMinutesSnapshot=10;request.DriverAcknowledgementTargetMinutesSnapshot=5;request.ApprovalBypassAllowedSnapshot=true;request.PostReviewRequiredSnapshot=true;request.RequiresPostReview=true;request.SubmittedAt=fixedAt.AddHours(6);
