static IEnumerable<string> Permissions(string role, string[] all) => role switch { "admin" => all, "dashboard" => [FleetPermissions.DashboardView, FleetPermissions.ReportView, FleetPermissions.ReportExport, FleetPermissions.CalendarView, FleetPermissions.MaintenanceView], "noOverride" => [FleetPermissions.MaintenanceView, FleetPermissions.MaintenanceManage, FleetPermissions.MaintenanceComplete,FleetPermissions.CapabilityView,FleetPermissions.CompatibilityView], "driver" or "previousDriver" => [FleetPermissions.DriverViewOwnJobs,FleetPermissions.DriverAcknowledge,FleetPermissions.DriverStart,FleetPermissions.DriverComplete,FleetPermissions.TripUploadAttachment], "requester"=>[FleetPermissions.RequestViewOwn,FleetPermissions.RequestCreate,FleetPermissions.RequestEditOwn,FleetPermissions.RequestSubmit,FleetPermissions.RequestCapabilityManageOwn,FleetPermissions.CompatibilityView,FleetPermissions.EmergencyCreate,FleetPermissions.EmergencyViewOwn],"dispatcher"=>[FleetPermissions.DispatchView,FleetPermissions.DispatchAssign,FleetPermissions.CompatibilityView,FleetPermissions.EmergencyViewQueue,FleetPermissions.EmergencyDispatch],"reviewer"=>[FleetPermissions.RequestViewOwn,FleetPermissions.RequestCreate,FleetPermissions.RequestEditOwn,FleetPermissions.RequestSubmit,FleetPermissions.AdminReviewApprove,FleetPermissions.AdminReviewReturn,FleetPermissions.AdminReviewReject,FleetPermissions.CalendarView,FleetPermissions.EmergencyReview,FleetPermissions.EmergencyViewAudit],"director"=>[FleetPermissions.RequestViewOwn,FleetPermissions.RequestCreate,FleetPermissions.RequestEditOwn,FleetPermissions.RequestSubmit,FleetPermissions.DirectorApprove,FleetPermissions.DirectorReturn,FleetPermissions.DirectorReject,FleetPermissions.CalendarView],_ => [FleetPermissions.MaintenanceView] };
static async Task Cleanup(AppDbContext db, QaManifest m)
{
    await using var tx = await db.Database.BeginTransactionAsync();
    var userIds = m.Users.Values.Select(x => x.Id).ToArray();
    if(!m.RunId.StartsWith("qa-",StringComparison.Ordinal)||userIds.Length<7)throw new InvalidOperationException("Manifest run identity is invalid.");
    var ownedUsers=await db.Users.CountAsync(x=>userIds.Contains(x.Id)&&x.Username.StartsWith(m.RunId));
    if(ownedUsers!=userIds.Length||!await db.Departments.AnyAsync(x=>x.Id==m.DepartmentId&&x.Name.StartsWith(m.RunId)))throw new InvalidOperationException("Manifest ownership validation failed.");
    var manifestRequestIds=new[]{m.RequestId,m.EmergencyQueueRequestId,m.DriverRequestId,m.DraftRequestId,m.AttachmentRequestId};
    if(await db.FleetRequests.CountAsync(x=>manifestRequestIds.Contains(x.Id)&&userIds.Contains(x.CreatedByUserId))!=manifestRequestIds.Length)throw new InvalidOperationException("Manifest contains a request outside its run.");
    var requestIds = await db.FleetRequests.Where(x=>userIds.Contains(x.CreatedByUserId)).Select(x=>x.Id).ToArrayAsync();
    var runSuffix = m.RunId.Substring(m.RunId.Length - 8);
    var vehicleIds = await db.FleetVehicles.Where(x => x.VehicleCode.Contains(runSuffix)).Select(x => x.Id).ToListAsync();
    var maintenanceIds = await db.FleetVehicleMaintenanceSchedules.Where(x => vehicleIds.Contains(x.VehicleId)).Select(x => x.Id).ToListAsync();
    var aggregateIds = vehicleIds.Concat(maintenanceIds).Concat(requestIds).Concat([m.AssignmentId, m.TripId, m.DriverAssignmentId, m.DriverTripId, m.AttachmentAssignmentId, m.AttachmentTripId, m.DocumentId]).Distinct().ToArray();
    var eventIds = await db.DomainEvents.Where(x => aggregateIds.Contains(x.AggregateId) || (x.ActorUserId.HasValue && userIds.Contains(x.ActorUserId.Value))).Select(x => x.EventId).ToListAsync();
    var outboxIds = await db.OutboxMessages.Where(x => eventIds.Contains(x.EventId)).Select(x => x.Id).ToListAsync();

    await db.NotificationDeliveries.Where(x => outboxIds.Contains(x.OutboxMessageId) || userIds.Contains(x.RecipientUserId)).ExecuteDeleteAsync();
    await db.Notifications.Where(x => x.UserId.HasValue && userIds.Contains(x.UserId.Value)).ExecuteDeleteAsync();
    await db.LineDeliveryLogs.Where(x => x.RecipientUserId.HasValue && userIds.Contains(x.RecipientUserId.Value)).ExecuteDeleteAsync();
    await db.OutboxMessages.Where(x => outboxIds.Contains(x.Id)).ExecuteDeleteAsync();
    await db.DomainEvents.Where(x => eventIds.Contains(x.EventId)).ExecuteDeleteAsync();
    await db.RefreshTokens.Where(x => userIds.Contains(x.UserId)).ExecuteDeleteAsync();
    await db.AuditLogs.Where(x => (x.UserId.HasValue && userIds.Contains(x.UserId.Value)) || (x.EffectiveActorUserId.HasValue && userIds.Contains(x.EffectiveActorUserId.Value))).ExecuteDeleteAsync();
    await db.FleetMaintenanceAttachments.Where(x => userIds.Contains(x.CreatedByUserId)).ExecuteDeleteAsync();
    await db.FleetTripAttachments.Where(x=>userIds.Contains(x.CreatedByUserId)).ExecuteDeleteAsync();
    await db.FleetVehicleMaintenanceRecords.Where(x => vehicleIds.Contains(x.VehicleId)).ExecuteDeleteAsync();
    await db.FleetVehicleMaintenanceSchedules.Where(x => vehicleIds.Contains(x.VehicleId)).ExecuteDeleteAsync();
    await db.FleetVehicleDocuments.Where(x => vehicleIds.Contains(x.VehicleId)).ExecuteDeleteAsync();
    await db.FleetCancellationRequests.Where(x => requestIds.Contains(x.FleetRequestId)).ExecuteDeleteAsync();
    await db.FleetEmergencyPostReviews.Where(x=>requestIds.Contains(x.FleetRequestId)).ExecuteDeleteAsync();
    await db.FleetCompatibilityOverrides.Where(x=>requestIds.Contains(x.FleetRequestId)).ExecuteDeleteAsync();
    await db.FleetRequestRequiredCapabilities.Where(x=>requestIds.Contains(x.FleetRequestId)).ExecuteDeleteAsync();
    await db.FleetTripRecords.Where(x => requestIds.Contains(x.FleetRequestId)).ExecuteDeleteAsync();
    await db.FleetAssignments.Where(x => requestIds.Contains(x.FleetRequestId)).ExecuteDeleteAsync();
    await db.FleetRequestStatusHistories.Where(x => requestIds.Contains(x.FleetRequestId)).ExecuteDeleteAsync();
    await db.FleetRequestPassengers.Where(x => requestIds.Contains(x.FleetRequestId)).ExecuteDeleteAsync();
    await db.FleetRequests.Where(x => requestIds.Contains(x.Id)).ExecuteDeleteAsync();
    await db.FleetVehicleUnavailability.Where(x => vehicleIds.Contains(x.VehicleId)).ExecuteDeleteAsync();
    await db.FleetDriverUnavailability.Where(x => userIds.Contains(x.UserId)).ExecuteDeleteAsync();
    await db.FleetDriverProfiles.Where(x => userIds.Contains(x.UserId)).ExecuteDeleteAsync();
    await db.FleetVehicleCapabilities.Where(x=>vehicleIds.Contains(x.VehicleId)).ExecuteDeleteAsync();
    var typeIds = await db.FleetVehicles.Where(x => vehicleIds.Contains(x.Id)).Select(x => x.VehicleTypeId).ToListAsync();
    await db.FleetVehicles.Where(x => vehicleIds.Contains(x.Id)).ExecuteDeleteAsync();
    await db.FleetVehicleTypes.Where(x => typeIds.Contains(x.Id)).ExecuteDeleteAsync();
    await db.FleetMaintenanceTypes.Where(x => x.Name.StartsWith(m.RunId)).ExecuteDeleteAsync();
    await db.FleetCapabilities.Where(x=>x.Id==m.CapabilityId||x.Id==m.SafetyCapabilityId||(x.CreatedByUserId.HasValue&&userIds.Contains(x.CreatedByUserId.Value))).ExecuteDeleteAsync();
    await db.FleetEmergencyPolicies.Where(x=>x.Id==m.EmergencyPolicyId).ExecuteDeleteAsync();
    await db.FleetRolloutSettings.Where(x => x.Id == m.RolloutSettingId).ExecuteDeleteAsync();
    await db.UserRoles.Where(x => userIds.Contains(x.UserId)).ExecuteDeleteAsync();
    var roleIds = await db.Roles.Where(x => x.Name.StartsWith(m.RunId)).Select(x => x.Id).ToListAsync();
    await db.RolePermissions.Where(x => roleIds.Contains(x.RoleId)).ExecuteDeleteAsync();
    await db.Roles.Where(x => roleIds.Contains(x.Id)).ExecuteDeleteAsync();
    await db.Users.Where(x => userIds.Contains(x.Id)).ExecuteDeleteAsync();
    await db.Departments.Where(x => x.Name.StartsWith(m.RunId)).ExecuteDeleteAsync();
    await tx.CommitAsync();
}
static string Required(string key) => Environment.GetEnvironmentVariable(key) ?? throw new InvalidOperationException($"{key} is required.");
record QaManifest(string RunId, DateTime FixedAt, Guid VehicleId, Guid MaintenanceId, Guid RequestId, Guid EmergencyQueueRequestId, Guid DriverRequestId, Guid DraftRequestId, Guid DriverAssignmentId, Guid DriverTripId, Guid AttachmentRequestId, Guid AttachmentAssignmentId, Guid AttachmentTripId, Guid AttachmentVehicleId, Guid AssignmentId, Guid TripId, Guid DocumentId, Guid RolloutSettingId,Guid CapabilityId,Guid MismatchCapabilityId,Guid SafetyCapabilityId,Guid EmergencyPolicyId,string EmergencyPolicyCode,Guid DepartmentId, Dictionary<string, QaUser> Users); record QaUser(Guid Id, string Username);
